function validate([A, B]) {
  if (!Array.isArray(A) || !Array.isArray(B)) return 'A and B must be arrays.';
  if (A.length < 1 || A.length > 50) return 'A needs 1 to 50 numbers.';
  if (B.length !== A.length) return 'A and B must have the same length.';
  const n = A.length;
  for (const [name, values] of [['A', A], ['B', B]]) {
    const seen = new Set();
    for (const value of values) {
      if (!Number.isInteger(value) || value < 1 || value > n) return name + ' holds whole numbers from 1 to n.';
      if (seen.has(value)) return name + ' must be a permutation: no repeated numbers.';
      seen.add(value);
    }
  }
  return null;
}

