function findThePrefixCommonArray(A, B) {
  // For every prefix length, build both prefix sets and intersect them.
  const answer = [];
  for (let i = 0; i < A.length; i++) {
    const left = new Set(A.slice(0, i + 1));
    const right = new Set(B.slice(0, i + 1));
    answer.push([...left].filter(value => right.has(value)).length);
  }
  return answer;
}

