function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? int(40, 50) : int(1, 8);
  const shuffled = () => {
    const values = Array.from({ length: n }, (_, i) => i + 1);
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [values[i], values[j]] = [values[j], values[i]];
    }
    return values;
  };
  const A = shuffled();
  const style = rand();
  if (style < 0.15) return [A, A.slice()];
  if (style < 0.3) return [A, A.slice().reverse()];
  if (style < 0.45) {
    // B is A with a few neighbouring swaps, so the prefixes overlap a lot.
    const B = A.slice();
    for (let k = 0; k < Math.max(1, n >> 2); k++) {
      const i = int(0, Math.max(0, n - 2));
      if (i + 1 < n) [B[i], B[i + 1]] = [B[i + 1], B[i]];
    }
    return [A, B];
  }
  return [A, shuffled()];
}
